<?php

if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

if (isset($_GET['lang']) && in_array($_GET['lang'], ['en', 'de'], true)) {
    $_SESSION['site_lang'] = $_GET['lang'];
}

function current_lang(): string {
    return $_SESSION['site_lang'] ?? 'en';
}

function current_url_with_lang(string $lang): string {
    $params = $_GET;
    $params['lang'] = $lang;

    $script = basename($_SERVER['PHP_SELF'] ?? 'index.php');
    if ($script === '' || $script === '/' || $script === '\\') {
        $script = 'index.php';
    }

    return $script . '?' . http_build_query($params);
}

