function t(string $text): string {
    if (current_lang() !== 'de') {
        return $text;
    }

    $map = tn_translation_map_de();
    return $map[$text] ?? $text;
}

function translate_output(string $html): string {
    if (current_lang() !== 'de') {
        return $html;
    }

    $map = tn_translation_map_de();
    uksort($map, static function ($a, $b) {
        return strlen($b) <=> strlen($a);
    });

    return strtr($html, $map);
}
